using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class NewGameMilitaryTests
{
    static WorldSession Start(string site="site:kofu",string lord="person:shingen")=>NewGameWorldTests.Session([NewGameWorldTests.Officer(site:site,role:StartTemplate.Retainer,lord:lord)]);
    static void At(WorldSession s,long t)=>NewGameWorldTests.At(s,t);
    static void Open(WorldSession s){foreach(var m in s.GetActorView(s.PlayerControl).Messages.Where(m=>m.KnownBody==null).ToArray())Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,m.Id,s.Revision).Code);}
    static NewMilitaryInput Input(WorldSession s,NewMilitaryAction a,long amount=0,FieldPoint? x=null,FieldPoint? y=null)=>new(new("request:military-test/"+s.Revision+"/"+a),a,amount,x,y);
    static void Send(WorldSession s,NewMilitaryAction a,long amount=0,FieldPoint? x=null,FieldPoint? y=null){var result=s.DecideNewMilitary(Input(s,a,amount,x,y),s.PlayerControl,s.Revision);Assert.True(result.Code==ResultCode.Accepted,result.VisibleReason);}
    static void Permit(WorldSession s){Send(s,NewMilitaryAction.Request);At(s,s.Seconds+2);Open(s);Send(s,NewMilitaryAction.Accept);At(s,s.Seconds+2);Open(s);}
    static void Pickup(WorldSession s){Permit(s);Send(s,NewMilitaryAction.Pickup);Send(s,NewMilitaryAction.Load,100000);}
    static void March(WorldSession s){Send(s,NewMilitaryAction.Deploy);var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());Send(s,NewMilitaryAction.Form,x:new(a.X+20000,a.Y-12000),y:new(a.X+20000,a.Y+12000));At(s,s.DiagnosticSnapshot().NewMilitary!.Orders.Last().Routes.SelectMany(x=>x).Max(x=>x.EndAt)+1);}
    static void Home(WorldSession s){Send(s,NewMilitaryAction.Recall);At(s,s.DiagnosticSnapshot().NewMilitary!.Orders.Last().Routes.SelectMany(x=>x).Max(x=>x.EndAt)+1);Send(s,NewMilitaryAction.Enter);Send(s,NewMilitaryAction.Unload,NewGameMilitary.View(s.DiagnosticSnapshot()).Carry);}
    [Theory][InlineData("site:kofu","person:shingen","org:takeda")][InlineData("site:odawara","person:ujiyasu","org:hojo")][InlineData("site:castle","person:nobunaga","org:oda")]
    public void SamePersonCompletesLocalLoan(string site,string lord,string owner){var s=Start(site,lord);var original=s.PlayerControl;Pickup(s);March(s);Home(s);Send(s,NewMilitaryAction.Report);Send(s,NewMilitaryAction.Return);At(s,s.Seconds+2);Open(s);Assert.Equal(original,s.PlayerControl);Assert.Contains(s.DiagnosticSnapshot().NewMilitary!.Events,e=>e.Effect==MilitaryEffect.Returned);Assert.All(s.DiagnosticSnapshot().Units,u=>{Assert.Equal(new EntityId(owner),u.Organization);Assert.Equal(new EntityId(lord),u.Commander);});Assert.All(s.DiagnosticSnapshot().ResourceLots,l=>Assert.Equal(new EntityId(owner),l.Owner));ContractValidation.Validate(s.DiagnosticSnapshot());}
    [Fact]public void MembershipIsNotPermission(){var s=Start();Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(Input(s,NewMilitaryAction.Pickup),s.PlayerControl,s.Revision).Code);Assert.Empty(s.DiagnosticSnapshot().Units);var parent=NewGameWorldTests.Officer("created:parent",StartTemplate.Retainer,"site:kofu","person:shingen");var child=NewGameWorldTests.Officer(role:StartTemplate.Subretainer,site:"site:kofu",lord:parent.Id);var sub=NewGameWorldTests.Session([child,parent]);Assert.False(NewGameMilitary.View(sub.DiagnosticSnapshot()).CanRequest);}
    [Fact]public void PermissionIsNotPickup(){var s=Start();Permit(s);Assert.All(s.DiagnosticSnapshot().Units,u=>Assert.Equal(new EntityId("person:shingen"),u.Commander));Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(Input(s,NewMilitaryAction.Deploy),s.PlayerControl,s.Revision).Code);}
    [Fact]public void UnopenedOfferCannotBeAccepted(){var s=Start();Send(s,NewMilitaryAction.Request);At(s,2);Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(Input(s,NewMilitaryAction.Accept),s.PlayerControl,s.Revision).Code);At(s,123);Open(s);Assert.False(NewGameMilitary.View(s.DiagnosticSnapshot()).CanAccept);Assert.Contains("期限切れ",NewGameMilitary.View(s.DiagnosticSnapshot()).Status);}
    [Fact]public void DispatchReplayHasOneEffect(){var s=Start();var i=Input(s,NewMilitaryAction.Request);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(i,s.PlayerControl,s.Revision).Code);string h=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.Equal(ResultCode.AlreadyAccepted,s.DecideNewMilitary(i,s.PlayerControl,0).Code);Assert.Equal(ResultCode.IdPayloadConflict,s.DecideNewMilitary(i with{Action=NewMilitaryAction.Accept},s.PlayerControl,s.Revision).Code);Assert.Equal(h,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}
    [Fact]public void ZeroStockCannotDeploy(){var s=Start();Permit(s);Send(s,NewMilitaryAction.Pickup);Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(Input(s,NewMilitaryAction.Deploy),s.PlayerControl,s.Revision).Code);}
    [Fact]public void ReportBeforeReturnDoesNotAuthorizeReturn(){var s=Start();Pickup(s);Send(s,NewMilitaryAction.Report);March(s);Send(s,NewMilitaryAction.Return);At(s,s.Seconds+3);Home(s);At(s,s.Seconds+2);Assert.DoesNotContain(s.DiagnosticSnapshot().NewMilitary!.Events,e=>e.Effect==MilitaryEffect.Returned);Send(s,NewMilitaryAction.Report);At(s,s.Seconds+2);Assert.Contains(s.DiagnosticSnapshot().NewMilitary!.Events,e=>e.Effect==MilitaryEffect.Returned);}
    [Fact]public void FieldTravelCannotAlsoStartRoadMove(){var s=Start();Pickup(s);var intent=TravelWorld.Move(s.DiagnosticSnapshot(),"request:move","castle");Send(s,NewMilitaryAction.Deploy);Assert.Equal(ResultCode.InvalidInput,s.Submit(intent,s.Revision).Code);}
    [Fact]public void ReturnRequestCannotGrantNewDeployment(){var s=Start();Pickup(s);Send(s,NewMilitaryAction.Return);Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(Input(s,NewMilitaryAction.Deploy),s.PlayerControl,s.Revision).Code);}
    [Fact]public void MilitaryIdCannotBecomeAnotherBusinessInput(){var s=Start();var i=Input(s,NewMilitaryAction.Request);s.DecideNewMilitary(i,s.PlayerControl,s.Revision);Assert.Equal(ResultCode.IdPayloadConflict,s.Submit(NewGameWorld.Inspect(s.DiagnosticSnapshot(),i.Id.Value),s.Revision).Code);}
    [Fact]public void PendingLoanPreventsServiceRelease(){var s=Start();Pickup(s);var c=NewGameService.View(s.DiagnosticSnapshot()).Cases.Single();Assert.Equal(ResultCode.Accepted,s.DecideService(new(new("request:leave"),CareerAction.RequestRelease,c.Case),s.PlayerControl,s.Revision).Code);At(s,2+s.Seconds);Assert.Contains(s.DiagnosticSnapshot().Service!.Events,e=>e.Kind==CareerEventKind.ReleaseWaiting);}
    [Fact]public void SaveAndSameFutureAreExact(){var s=Start();Pickup(s);March(s);var copy=new WorldSession(ContractJson.Read<ContractWorld>(ContractJson.Write(s.DiagnosticSnapshot())));foreach(var x in new[]{s,copy}){Home(x);Send(x,NewMilitaryAction.Report);Send(x,NewMilitaryAction.Return);At(x,x.Seconds+2);Open(x);}Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(copy.DiagnosticSnapshot()));}
    [Fact]public void NoMilitaryKeepsOldOptionalJsonAbsent(){var w=Start().DiagnosticSnapshot();Assert.DoesNotContain("\"NewMilitary\"",System.Text.Encoding.UTF8.GetString(ContractJson.Write(w)));}
    [Theory][InlineData("owner")][InlineData("stock")][InlineData("notice")][InlineData("route")][InlineData("use")]
    public void ForgedMilitaryStateIsRejected(string part){var s=Start();Pickup(s);March(s);var w=s.DiagnosticSnapshot();if(part=="owner")w.Units=w.Units.Select(u=>u with{Organization=new("org:oda")}).ToArray();if(part=="stock")w.ResourceLots=w.ResourceLots.Select(l=>l with{Quantity=l.Quantity+1}).ToArray();if(part=="notice")w.Messaging.Messages=w.Messaging.Messages.Select(m=>m.Kind=="new-military-notice"?m with{Body="forged"}:m).ToArray();if(part=="route")w.NewMilitary=w.NewMilitary! with{Orders=w.NewMilitary.Orders.Select(o=>o with{Origins=[new(1,1),..o.Origins[1..]]}).ToArray()};if(part=="use")w.NewMilitary=w.NewMilitary! with{Uses=[]};Assert.Throws<InvalidDataException>(()=>ContractValidation.Validate(w));}
    [Fact]public void ReturnUnblocksSameRevisionServiceDepartureAndRoadTravel(){var s=Start();Pickup(s);March(s);Send(s,NewMilitaryAction.Return);var c=NewGameService.View(s.DiagnosticSnapshot()).Cases.Single();s.DecideService(new(new("request:leave"),CareerAction.RequestRelease,c.Case),s.PlayerControl,s.Revision);Home(s);Send(s,NewMilitaryAction.Report);At(s,s.Seconds+3);Open(s);Assert.Null(NewGameService.View(s.DiagnosticSnapshot()).House);Assert.Equal(ResultCode.Accepted,s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:next-life","castle"),s.Revision).Code);At(s,s.Seconds+5);Assert.True(s.GetBranchView(s.PlayerControl).Walking);}
    [Fact]public void ReceivedReportUsesPhysicalFirstMile(){var s=Start();Pickup(s);March(s);Send(s,NewMilitaryAction.Return);var w=s.DiagnosticSnapshot();var msg=w.NewMilitary!.Requests.Last().Message;var courier=w.Couriers!.Missions.Single(c=>w.Messaging.Attempts.Single(a=>a.Id==c.Attempt).MessageId==msg);Assert.NotEmpty(courier.FirstMile!);Assert.True(courier.ReadyAt>s.Seconds+1);Assert.DoesNotContain(w.NewMilitary.Events,e=>e.Effect==MilitaryEffect.Returned);}
    [Fact]public void ExistingGenerationStoreKeepsImmutableDefinitions(){var s=Start();var definitions=s.DiagnosticSnapshot().Definitions;Pickup(s);March(s);Assert.Equal(ContractJson.CanonicalHash(definitions),ContractJson.CanonicalHash(s.DiagnosticSnapshot().Definitions));string path=Path.Combine(Path.GetTempPath(),"military-save-"+Guid.NewGuid().ToString("N"));var store=new GenerationSaveStore(path,definitions);s.SetPaused(true);store.Save(s,"manual",s.DiagnosticSnapshot().WorldId,new(0,1,null,new(0,0,50,15,true,true)));var host=new WorldSessionHost(s);Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("manual"),s,s.Revision));Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(host.Current.DiagnosticSnapshot()));}
    [Fact]public void OverCapacityStockDoesNotMutateWorld(){var s=Start();Permit(s);Send(s,NewMilitaryAction.Pickup);string h=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(Input(s,NewMilitaryAction.Load,NewGameMilitary.Capacity+1),s.PlayerControl,s.Revision).Code);Assert.Equal(h,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}
    [Fact]public void RemoteLoadingIsRejected(){var s=Start();Pickup(s);Send(s,NewMilitaryAction.Deploy);Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(Input(s,NewMilitaryAction.Load,1),s.PlayerControl,s.Revision).Code);}
    [Fact]public void InquiryDoesNotForgeOriginalOpening(){var s=Start();Send(s,NewMilitaryAction.Request);At(s,2);Open(s);Send(s,NewMilitaryAction.Accept);At(s,4);var original=s.DiagnosticSnapshot().NewMilitary!.Events.Single(e=>e.Effect==MilitaryEffect.Permission);Assert.False(NewGameMilitary.View(s.DiagnosticSnapshot()).CanPickup);Send(s,NewMilitaryAction.Inquire);At(s,6);var quote=s.DiagnosticSnapshot().NewMilitary!.Events.Single(e=>e.Effect==MilitaryEffect.StatusSent);Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,new(quote.Message),s.Revision).Code);Assert.True(NewGameMilitary.View(s.DiagnosticSnapshot()).CanPickup);Assert.DoesNotContain(s.DiagnosticSnapshot().NewMilitary!.Openings,o=>o.Message==original.Message);}
    [Fact]public void CreatedLordIsNotReplacedWithNobunaga(){var head=NewGameWorldTests.Officer("created:head",StartTemplate.Daimyo,"site:kofu");var player=NewGameWorldTests.Officer(site:"site:kofu",role:StartTemplate.Retainer,lord:head.Id);var setup=NewGameWorldTests.Setup([head,player],[new(head.Id,"org:created-head",["site:kofu"],false)]);var s=new WorldSession(NewGameWorld.Create(setup.World,setup.Registered,player.Id));Pickup(s);Assert.Equal(new EntityId(head.Id),s.DiagnosticSnapshot().NewMilitary!.Terms.Principal);Assert.All(s.DiagnosticSnapshot().Units,u=>Assert.Equal(new EntityId("org:created-head"),u.Organization));}
    [Fact]public void WholeAndChunkedTimeHaveSameConsumption(){var s=Start();Pickup(s);March(s);var copy=new WorldSession(ContractJson.Copy(s.DiagnosticSnapshot()));At(s,s.Seconds+5);for(int i=0;i<5;i++)At(copy,copy.Seconds+1);Assert.Equal(s.DiagnosticSnapshot().NewMilitary!.Uses,copy.DiagnosticSnapshot().NewMilitary!.Uses);Assert.Equal(NewGameMilitary.View(s.DiagnosticSnapshot()).Carry,NewGameMilitary.View(copy.DiagnosticSnapshot()).Carry);}

}
